#!/usr/bin/env python3
"""Restore frozen v318 source only. Never executes a solver or registers evals."""
from pathlib import Path
import base64,difflib,hashlib,json,zlib
ROOT=Path(__file__).resolve().parents[2]
PARENT='364cab41a22ccb8c5d84bb0b74086dbb4d1ffd635ad735fcdf8231efa21e3538'
EXPECTED='24de5a028ff3fcb97d1c1b6afbc1f9b3255865644a22057fb13243d15b99999d'
DATA=''
# Correct a text-transport-only insertion; the output hash certifies the evaluated source.
DATA=DATA.replace('M+nTQ19','M+nQ19')
source=ROOT/'src/bin/v315_reactive_racing.cpp'
original=source.read_text()
assert hashlib.sha256(original.encode()).hexdigest()==PARENT,'v315 parent changed'
lines=original.splitlines(keepends=True)
for first,last,replacement in reversed(json.loads(zlib.decompress(base64.b64decode(DATA)))):
    lines[first:last]=replacement
text=''.join(lines)
assert hashlib.sha256(text.encode()).hexdigest()==EXPECTED,'materialized v318 hash mismatch'
path=ROOT/'src/bin/v318_bit_parallel_history.cpp'
if path.exists():assert path.read_text()==text,'refusing to overwrite different v318'
else:path.write_text(text)
out=ROOT/'adhoc/v318';out.mkdir(parents=True,exist_ok=True)
(out/'v318_vs_v315.patch').write_text(''.join(difflib.unified_diff(original.splitlines(True),text.splitlines(True),fromfile='a/src/bin/v315_reactive_racing.cpp',tofile='b/src/bin/v318_bit_parallel_history.cpp')))
print(EXPECTED)
